func valueSequenceConfig(p unsafe.Pointer, c int32) any {
	r := (*sequenceconfig.SequenceConfig)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.SequenceType)
	case 4:
		return r.Prefix
	case 5:
		return r.IncludeYear
	case 6:
		return r.YearDigits
	case 7:
		return r.IncludeMonth
	case 8:
		return r.IncludeWeekNumber
	case 9:
		return r.IncludeDay
	case 10:
		return r.SequenceDigits
	case 11:
		return r.IncludeLocationCode
	case 12:
		return r.IncludeRandomDigits
	case 13:
		return r.RandomDigitsCount
	case 14:
		return r.IncludeCheckDigit
	case 15:
		return r.IncludeBusinessUnitCode
	case 16:
		return r.UseSeparators
	case 17:
		return r.SeparatorChar
	case 18:
		return r.AllowCustomFormat
	case 19:
		return r.CustomFormat
	case 20:
		if r.LocationCodeStrategy == nil {
			return nil
		}
		return *r.LocationCodeStrategy
	case 21:
		return r.Version
	case 22:
		return r.CreatedAt
	case 23:
		return r.UpdatedAt
	}
	return nil
}

